from __future__ import annotations

from datetime import date

import polars as pl
from src.backtest.strategy import MarketView, Signal, Strategy


class MeanReversion50d(Strategy):
    rationale = (
        "This strategy exploits short-horizon mean reversion by identifying stocks that have "
        "deviated significantly from their historical price levels and entering short positions "
        "when the stock price crosses below its 50-day moving average, anticipating a return to "
        "the long-term average."
    )

    def __init__(self, window: int = 50, top_n: int = 20) -> None:
        self._window = window
        self._top_n = top_n

    def generate(self, view: MarketView) -> Signal:
        stamp = _latest_visible(view)
        closes = view.closes(lookback=self._window)
        if closes.height < self._window:
            return Signal(information_available_at=stamp, weights={})

        smas: pl.DataFrame = (
            view.history().group_by("symbol")
                         .agg((pl.col("adj_close").mean()).alias("50d_sma"))
        )
        ranked_closes = (closes
                         .join(smas, on="symbol", how="inner")
                         .with_columns(
                             (pl.col("adj_close") - pl.col("50d_sma")).abs().alias("deviation"),
                             ((pl.col("session_date") == stamp) & 
                              (pl.col("adj_close") < pl.col("50d_sma"))).alias("cross_below")
                         )
                         .sort("deviation", descending=True)
        )

        picks: list[str] = [symbol for symbol, row in ranked_closes.iter_rows() if row["cross_below"]]
        picks = picks[:self._top_n]
        if not picks:
            return Signal(information_available_at=stamp, weights={})

        weight = 0.05 / len(picks)
        return Signal(
            information_available_at=stamp, 
            weights={s: weight for s in picks}
        )


def _latest_visible(view: MarketView) -> date:
    visible = view.history()
    if visible.is_empty():
        return date(1900, 1, 1)
    newest = visible["session_date"].max()
    assert isinstance(newest, date)
    return newest
